    <title>Terms Consent</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #eef2ff;
        --card: #ffffff;
        --text: #172033;
        --muted: #5c667a;
        --primary: #355cff;
        --primary-hover: #2447d9;
        --border: #d8deea;
        --error: #b42318;
        --ring: #ffbf47;
        --shadow: 0 24px 70px rgba(38, 52, 90, 0.18);
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top left, rgba(53, 92, 255, 0.18), transparent 32rem),
          linear-gradient(135deg, #f8fbff 0%, var(--bg) 100%);
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        transform: translateY(-150%);
        border-radius: 999px;
        background: var(--text);
        color: #fff;
        padding: 0.75rem 1rem;
        text-decoration: none;
        font-weight: 700;
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 3px solid var(--ring);
        outline-offset: 3px;
      }

