        border: 1px solid rgba(216, 222, 234, 0.9);
        border-radius: 1.5rem;
        background: rgba(255, 255, 255, 0.92);
        box-shadow: var(--shadow);
        padding: clamp(1.25rem, 5vw, 2.25rem);
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        color: var(--primary);
        font-size: 0.82rem;
        font-weight: 800;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 7vw, 3rem);
        line-height: 1.05;
        letter-spacing: -0.045em;
      }

      .intro {
        margin: 1rem 0 0;
        color: var(--muted);
        font-size: 1.03rem;
        line-height: 1.6;
      }

      form {
        display: grid;
        gap: 1.25rem;
        margin-top: 1.75rem;
      }

      .required-note {
        margin: 0;
        color: var(--muted);
        font-size: 0.92rem;
      }

      .form-field {
        border: 1px solid var(--border);
        border-radius: 1rem;
        background: #f8faff;
        padding: 1rem;
      }

      .checkbox-row {
        display: grid;
        grid-template-columns: 1.35rem 1fr;
        gap: 0.8rem;
        align-items: start;
      }

      input[type="checkbox"] {
        width: 1.35rem;
        height: 1.35rem;
        margin: 0.12rem 0 0;
        accent-color: var(--primary);
        cursor: pointer;
      }

      label {
        color: var(--text);
        font-weight: 750;
        line-height: 1.45;
        cursor: pointer;
      }

      .required-marker {
        color: var(--error);
