      .helper-text {
        color: var(--muted);
      }

      .error-text {
        color: var(--error);
        font-weight: 700;
      }

      .form-field:has(input[aria-invalid="true"]) {
        border-color: var(--error);
        background: #fff8f7;
      }

      button {
        min-height: 3rem;
        border: 0;
        border-radius: 999px;
        background: var(--primary);
        color: #fff;
        padding: 0.9rem 1.25rem;
        font: inherit;
        font-weight: 800;
        cursor: pointer;
        box-shadow: 0 12px 28px rgba(53, 92, 255, 0.28);
      }

      button:hover {
        background: var(--primary-hover);
      }

      button:focus-visible,
      input[type="checkbox"]:focus-visible {
        outline: 3px solid var(--ring);
        outline-offset: 4px;
      }

      .status {
        min-height: 1.5rem;
        margin: 0;
        color: #146c43;
        font-weight: 700;
      }

      [hidden] {
        display: none;
      }

      @media (forced-colors: active) {
        .card,
        .form-field,
        button {
          border: 1px solid CanvasText;
          box-shadow: none;
        }

        button:focus-visible,
        input[type="checkbox"]:focus-visible,
        .skip-link:focus {
          outline: 3px solid Highlight;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="root"></div>

    <script>
      function Header() {
        return `
          <p class="eyebrow">Consent required</p>
          <h1>Review and continue</h1>
          <p class="intro">
            Confirm that you accept the terms before submitting this form.
          </p>
        `;
      }

      function ConsentCheckbox() {
        return `
          <div class="form-field">
            <div class="checkbox-row">
              <input
                id="terms-consent"
                name="termsConsent"
                type="checkbox"
                required
                aria-describedby="terms-consent-help terms-consent-error"
              >
              <label for="terms-consent">
                I agree to the Terms of Use
                <span class="required-marker" aria-hidden="true">*</span>
              </label>
            </div>
            <p id="terms-consent-help" class="helper-text">
              Required to create and manage your account.
            </p>
            <p id="terms-consent-error" class="error-text" hidden>
              Error: You must agree to the Terms of Use before continuing.
            </p>
          </div>
        `;
      }

      function ConsentForm() {
        return `
          <form id="consent-form" novalidate>
            <p class="required-note">
              Fields marked with <span class="required-marker" aria-hidden="true">*</span> are required.
            </p>
            ${ConsentCheckbox()}
            <button type="submit">Continue</button>
            <p id="form-status" class="status" aria-live="polite"></p>
          </form>
        `;
      }

      function App() {
        return `
          <div class="page-shell">
            <main id="main-content">
              <section class="card" aria-labelledby="page-title">
                ${Header().replace("<h1>", '<h1 id="page-title">')}
                ${ConsentForm()}
              </section>
            </main>
          </div>
        `;
      }

      function setCheckboxError(checkbox, error, status, hasError) {
        checkbox.setAttribute("aria-invalid", String(hasError));
        error.hidden = !hasError;
        status.textContent = "";
      }

      function wireForm() {
        const form = document.querySelector("#consent-form");
        const checkbox = document.querySelector("#terms-consent");
        const error = document.querySelector("#terms-consent-error");
        const status = document.querySelector("#form-status");

        form.addEventListener("submit", (event) => {
          event.preventDefault();

          if (!checkbox.checked) {
            setCheckboxError(checkbox, error, status, true);
            checkbox.focus();
            return;
          }

          setCheckboxError(checkbox, error, status, false);
          status.textContent = "Terms accepted. Form submitted.";
        });

        checkbox.addEventListener("change", () => {
          if (checkbox.checked) {
            setCheckboxError(checkbox, error, status, false);
          }
        });
      }

      document.querySelector("#root").innerHTML = App();
      wireForm();
    </script>
  </body>
</html>
